alter table public.integrations add column if not exists sync_locked_until timestamptz;
alter table public.integrations add column if not exists last_sync_attempt_at timestamptz;
create or replace function public.acquire_integration_sync_lock(target_integration_id uuid,target_organisation_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare acquired uuid;begin if not public.has_organisation_role(target_organisation_id,array['owner','admin','manager']) then return false;end if;update public.integrations set sync_locked_until=now()+interval '10 minutes',last_sync_attempt_at=now() where id=target_integration_id and organisation_id=target_organisation_id and (sync_locked_until is null or sync_locked_until<now()) returning id into acquired;return acquired is not null;end$$;
create or replace function public.release_integration_sync_lock(target_integration_id uuid,target_organisation_id uuid) returns void language sql security definer set search_path=public as $$update public.integrations set sync_locked_until=null where id=target_integration_id and organisation_id=target_organisation_id and public.has_organisation_role(target_organisation_id,array['owner','admin','manager'])$$;
revoke all on function public.acquire_integration_sync_lock(uuid,uuid) from public;grant execute on function public.acquire_integration_sync_lock(uuid,uuid) to authenticated;
revoke all on function public.release_integration_sync_lock(uuid,uuid) from public;grant execute on function public.release_integration_sync_lock(uuid,uuid) to authenticated;
